-- E2E-only fixtures for the redesigned Class -> Subject -> optional Group architecture.
-- Load only after a local `supabase db reset`; never use against hosted projects.

on conflict (id) do update set
  first_name_en=excluded.first_name_en,last_name_en=excluded.last_name_en,
  first_name_ar=excluded.first_name_ar,last_name_ar=excluded.last_name_ar,is_active=true;

on conflict (id) do update set name_en=excluded.name_en,name_ar=excluded.name_ar,is_active=true;

on conflict (id) do update set name_en=excluded.name_en,name_ar=excluded.name_ar,is_active=true;

on conflict (id) do update set class_id=excluded.class_id,subject_id=excluded.subject_id,is_active=true;

on conflict (id) do update set name_en=excluded.name_en,name_ar=excluded.name_ar,is_active=true;

update public.class_subjects
set default_group_id = '14000000-0000-0000-0000-000000000001'
where id = '13000000-0000-0000-0000-000000000002';

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;
